```javascript
const { Client, GatewayIntentBits, PermissionsBitField } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.on('ready', () => {
  console.log('Bot listo');
});

client.on('messageCreate', async (message) => {
  if (message.content === 'ban') {
    if (!message.member.permissions.has(PermissionsBitField.Flags.BanMembers)) {
      return message.reply('No tienes permiso para banear');
    }

    const user = await message.mentions.users.first();
    if (!user) {
      return message.reply('Debes mencionar a un usuario para banearlo');
    }

    const member = message.guild.members.cache.get(user.id);
    if (!member) {
      return message.reply('El usuario mencionado no está en este servidor');
    }

    await member.ban();
    message.reply(`Usuario ${user.username} ha sido banido del servidor`);
  }
});

client.login(process.env.TOKEN);
```

En este código, se crea un cliente de Discord.js v14 y se establecen los intentos necesarios para manejar mensajes de texto y menciones de usuarios. El evento "messageCreate" escucha los mensajes enviados en el servidor y verifica si el comando "ban" es mencionado. Si el usuario que envía el comando no tiene los permisos necesarios para banear, se envía una respuesta de error. Si no se menciona a un usuario, se envía otra respuesta de error. Si el usuario mencionado no está en el servidor, se envía otra respuesta de error. Si todas las condiciones son verdaderas, el bot baneará al usuario mencionado y enviará una respuesta de éxito. Finalmente, se inicia la sesión del bot utilizando la clave de token en la variable de entorno `process.env.TOKEN`.

