Aquí está la función en C++ que convierte texto con formato markdown a texto con formato HTML:

```cpp
#include <iostream>
#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Reemplazar los enlaces
    std::regex link_regex("(\\[\\()([^\\]]+?)\\]\\()(\\().*?\\)\\)");
    std::string html = std::regex_replace(markdown, link_regex,
        "[\\1<a href=\\3>\\2</a>\\4]");

    // Reemplazar los títulos
    std::regex title_regex("^(#{1,6})\\s(.*)$");
    std::string title;
    while (std::regex_search(markdown, title_regex, std::back_inserter(title))) {
        std::string level = title[0];
        std::string text = title[1];
        html += std::string(level.size(), ' ') + "<h" + std::to_string(level.size()) + ">" + text + "</h" + std::to_string(level.size()) + ">\n";
        markdown.erase(0, title.position() + title.length());
    }

    // Reemplazar las listas
    std::regex list_regex("^(-|\\*|\\d+\\. )(.*)$");
    while (std::regex_search(markdown, list_regex, std::back_inserter(title))) {
        std::string marker = title[1];
        std::string text = title[2];
        html += std::string(marker.size(), ' ') + "<ul><li>" + text + "</li></ul>\n";
        markdown.erase(0, title.position() + title.length());
    }

    // Reemplazar los citas
    std::regex quote_regex("^(>+)\\s(.*)$");
    while (std::regex_search(markdown, quote_regex, std::back_inserter(title))) {
        std::string level = title[1];
        std::string text = title[2];
        html += std::string(level.size(), ' ') + "<blockquote>" + text + "</blockquote>\n";
        markdown.erase(0, title.position() + title.length());
    }

    // Reemplazar los código blocks
    std::regex code_block_regex("^(```)([a-z\\-]+)\\n(.*?)(?=\\n\\1\\s*$)");
    while (std::regex_search(markdown, code_block_regex, std::back_inserter(title))) {
        std::string language = title[2];
        std::string code = title[3];
        html += "<pre><code class='language-" + language + "'>" + code + "</code></pre>\n";
        markdown.erase(0, title.position() + title.length());
    }

    // Reemplazar las lineas horizontales
    std::regex hr_regex("^(-{3,})$");
    while (std::regex_search(markdown, hr_regex, std::back_inserter(title))) {
        html += "<hr>\n";
        markdown.erase(0, title.position() + title.length());
    }

    return html;
}

int main() {
    std::string markdown = "Hace [un tiempo](https://example.com) que estoy aprendiendo a programar en C++. # Título de nivel 1\n"
                           "## Título de nivel 2\n"
                           "### Título de nivel 3\n"
                           "\n"
                           "Aquí hay una lista:\n"
                           "- Item 1\n"
                           "- Item 2\n"
                           "1. Item 3\n"
                           "2. Item 4\n\n"
                           "Aquí hay una cita:\n"
                           "> Esta es una cita de ejemplo.\n"
                           ">> Esta es una subcita.\n"
                           ">>> Esta es una sub-subcita.\n\n"
                           "Aquí hay un bloque de código:\n"
                           "```cpp\n"
                           "int main() {\n"
                           "    std::cout << \"Hola, mundo!\" << std::endl;\n"
                           "    return 0;\n"
                           "}\n"
                           "```";

    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Este código define una función llamada `markdownToHtml` que toma una referencia a una cadena de texto en formato Markdown y devuelve una cadena de texto en formato HTML. La función utiliza expresiones regulares para reemplazar los enlaces, títulos, listas, citas, bloques de código y líneas horizontales en el texto de entrada con sus equivalentes HTML. El código también incluye un ejemplo de uso de la función en el main para probar su funcionamiento.

